UPDATE ins_comment
   SET content = #{content}
 WHERE comment_id = #{commentId}
   AND member_id  = #{memberId}
   AND deleted_yn = 'N'

UPDATE ins_comment
   SET deleted_yn = 'Y'
 WHERE comment_id = #{commentId}
   AND member_id  = #{memberId}
   AND deleted_yn = 'N'

